"use client";

import Image from "next/image";
import CollectionsPane from "./CollectionsPane";
import { handleImportCurl } from "./importCurl";
import * as buildCurl from "./buildCurl";
import * as util from "./util";
import { useApiPlaygroundState } from "./useApiPlaygroundState";
import styles from "./apiPlayground.module.css";
import * as springCall from "../components/springApiCalls";

export default function ApiPlaygroundPage() {
    const { collections, expandedCollectionIds, method, setMethod, url, setUrl, paramsRows, setParamsRows, headerRows,
        setHeaderRows, bodyInput, setBodyInput, activeTab, setActiveTab, importCurlText, setImportCurlText, importMessage,
        setImportMessage, copyMessage, setCopyMessage, saveMessage, isSaveDialogOpen, saveCollectionName, setSaveCollectionName,
        saveRequestName, setSaveRequestName, savedCollectionNoticeId, collectionsPaneMessage, showSuccessToast, setShowSuccessToast,
        responsePreview, setResponsePreview, canSendBody, toggleSaveDialog, saveRequestToCollection, toggleCollectionExpanded,
        addCollection, removeCollection, openSavedRequest, setResetRequestState, buildApiExecuteJson } = useApiPlaygroundState();

    const { requestUrlPreview } = buildCurl.buildRequestUrlPreview({ paramsRows, url });
    const isInvalidSaveMessage = saveMessage === util.SAVE_MESSAGE_INVALID_REQUEST;
    const isSelectCollectionMessage = saveMessage === util.SAVE_MESSAGE_SELECT_COLLECTION;
    const { curlCommand } = buildCurl.buildCurlParts({ headerRows, canSendBody, bodyInput, method, requestUrlPreview });

    const onImportCurlClick = () => {
        handleImportCurl({
            importCurlText, setUrl, setParamsRows, setHeaderRows, setBodyInput, setMethod, setImportCurlText,
            setImportMessage, setShowSuccessToast, setActiveTab
        });
    };

    const onCopyCurlClick = () => {
        buildCurl.onCopyCurlClick({ curlCommand, setCopyMessage });
    };

    const onNewClick = () => {
        setResetRequestState("new", {});
    };

    const onSendClick = async () => {
        setResponsePreview('{"message": "Loading..."}');
        try {
            const response = await springCall.executeCurlRequest(buildApiExecuteJson());
            setResponsePreview(JSON.stringify(response, null, 2));
        } catch (err) {
            setResponsePreview(JSON.stringify({ error: err.message }, null, 2));
        }
    };

    return (
        <main className={styles.main} style={{ fontFamily: util.APP_FONT }}>
            {showSuccessToast && (
                <div className={styles.toast}>
                    Imported cURL successfully.
                </div>
            )}

            <div className={styles.layout}>
                <CollectionsPane
                    collections={collections}
                    expandedCollectionIds={expandedCollectionIds}
                    savedCollectionNoticeId={savedCollectionNoticeId}
                    collectionsPaneMessage={collectionsPaneMessage}
                    onToggleCollection={toggleCollectionExpanded}
                    onOpenRequest={openSavedRequest}
                    onAddCollection={addCollection}
                    onRemoveCollection={removeCollection}
                />

                <section className={styles.section}>

                    <div className={styles.requestRow}>
                        <select
                            value={method}
                            onChange={(e) => setMethod(e.target.value)}
                            className={styles.methodSelect}
                        >
                            {util.HTTP_METHODS.map((httpMethod) => (
                                <option key={httpMethod} value={httpMethod}>
                                    {httpMethod}
                                </option>
                            ))}
                        </select>

                        <input
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="Enter request URL"
                            className={styles.urlInput}
                        />
                        <button
                            type="button"
                            onClick={onSendClick}
                            className={styles.primaryBtn}
                        >Send</button>
                        <button
                            type="button"
                            onClick={onNewClick}
                            className={styles.primaryBtn}
                        >Cancel</button>

                    </div>

                    <div className={styles.requestUrlPreview}>
                        Request URL: {requestUrlPreview}
                    </div>

                    <div className={styles.tabsRow}>
                        {util.REQUEST_TABS.map((tab) => {
                            const isActive = activeTab === tab;

                            return (
                                <button
                                    key={tab}
                                    type="button"
                                    onClick={() => setActiveTab(tab)}
                                    className={`${styles.tabButton} ${isActive ? styles.tabButtonActive : styles.tabButtonInactive}`}
                                >
                                    {tab}
                                </button>
                            );
                        })}

                        <div className={styles.rightActions}>
                            <button
                                type="button"
                                onClick={onNewClick}
                                className={styles.secondaryBtn}
                            >
                                New
                            </button>
                            <button
                                type="button"
                                onClick={() => toggleSaveDialog("open")}
                                className={styles.secondaryBtn}
                            >
                                Save to Collection
                            </button>
                            {saveMessage && isInvalidSaveMessage && (
                                <span className={`${styles.saveStatus} ${isInvalidSaveMessage ? styles.saveStatusError : ""}`}>
                                    {saveMessage}
                                </span>
                            )}
                        </div>
                    </div>

                    {activeTab === "Params" && (
                        <div className={styles.tabPanel}>
                            <div className={styles.dataCard}>
                                <div className={styles.tableHeaderRow} style={{ gridTemplateColumns: util.TABLE_COLUMNS }}>
                                    <div className={styles.tableHeaderCell}>On</div>
                                    <div className={styles.tableHeaderCell}>Key</div>
                                    <div className={styles.tableHeaderCell}>Value</div>
                                    <div className={styles.tableHeaderCell}>Description</div>
                                    <div className={styles.tableHeaderCell} />
                                </div>

                                <div className={styles.tableBody}>
                                    {paramsRows.map((row, rowIndex) => (
                                        <div key={`param-${rowIndex}`} className={styles.tableDataRow} style={{ gridTemplateColumns: util.TABLE_COLUMNS }}>
                                            <div className={styles.tableCellPad}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => util.updateRow(setParamsRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => util.updateRow(setParamsRows, rowIndex, "key", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => util.updateRow(setParamsRows, rowIndex, "value", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => util.updateRow(setParamsRows, rowIndex, "description", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => util.removeRow(setParamsRows, rowIndex)}
                                                className={styles.iconBtn}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => util.addRow(setParamsRows)}
                                    className={styles.addRowBtn}
                                >
                                    + Add Param
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Headers" && (
                        <div className={styles.tabPanel}>
                            <div className={styles.dataCard}>
                                <div className={styles.tableHeaderRow} style={{ gridTemplateColumns: util.TABLE_COLUMNS }}>
                                    <div className={styles.tableHeaderCell}>On</div>
                                    <div className={styles.tableHeaderCell}>Key</div>
                                    <div className={styles.tableHeaderCell}>Value</div>
                                    <div className={styles.tableHeaderCell}>Description</div>
                                    <div className={styles.tableHeaderCell} />
                                </div>

                                <div className={styles.tableBody}>
                                    {headerRows.map((row, rowIndex) => (
                                        <div key={`header-${rowIndex}`} className={styles.tableDataRow} style={{ gridTemplateColumns: util.TABLE_COLUMNS }}>
                                            <div className={styles.tableCellPad}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => util.updateRow(setHeaderRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => util.updateRow(setHeaderRows, rowIndex, "key", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => util.updateRow(setHeaderRows, rowIndex, "value", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => util.updateRow(setHeaderRows, rowIndex, "description", e.target.value)}
                                                className={styles.tableInput}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => util.removeRow(setHeaderRows, rowIndex)}
                                                className={styles.iconBtn}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => util.addRow(setHeaderRows)}
                                    className={styles.addRowBtn}
                                >
                                    + Add Header
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Body" && (
                        <div className={styles.textareaWrap}>
                            <textarea
                                value={bodyInput}
                                onChange={(e) => setBodyInput(e.target.value)}
                                onBlur={() => setBodyInput((prev) => util.formatJson(prev))}
                                disabled={!canSendBody}
                                className={`${styles.textarea} ${canSendBody ? styles.textareaEnabled : styles.textareaDisabled}`}
                            />
                        </div>
                    )}

                    {activeTab === "cURL" && (
                        <div className={styles.curlWrap}>
                            <div className={styles.curlRelative}>
                                <button
                                    type="button"
                                    onClick={onCopyCurlClick}
                                    className={styles.copyBtn}
                                    aria-label="Copy cURL"
                                    title="Copy cURL"
                                >
                                    <Image src="/assets/copy.svg" alt="" width={16} height={16} aria-hidden="true" />
                                </button>
                                {copyMessage && (
                                    <span className={styles.copyMessage}>
                                        {copyMessage}
                                    </span>
                                )}

                                <textarea
                                    value={curlCommand}
                                    readOnly
                                    className={`${styles.textarea} ${styles.textareaReadOnly}`}
                                />
                            </div>
                        </div>
                    )}

                    {activeTab === "Import cURL" && (
                        <div className={styles.importPanel}>
                            <textarea
                                value={importCurlText}
                                onChange={(e) => setImportCurlText(e.target.value)}
                                placeholder="Paste cURL here..."
                                className={`${styles.textarea} ${styles.textareaEnabled}`}
                            />

                            <div className={styles.importActions}>
                                <button
                                    type="button"
                                    onClick={onImportCurlClick}
                                    className={styles.primaryBtn}
                                >
                                    Import to Request
                                </button>

                                <span className={styles.importStatus}>{importMessage}</span>
                            </div>
                        </div>
                    )}

                    <div className={styles.responseSection}>
                        <div className={styles.responseTitle}>Response</div>
                        <textarea
                            value={responsePreview}
                            readOnly
                            className={styles.responseText}
                        />
                    </div>
                </section>
            </div>

            {isSaveDialogOpen && (
                <div className={styles.overlay}>
                    <div className={styles.modal}>
                        <div className={styles.modalTitle}>Save Request</div>
                        <div className={styles.modalText}>
                            Select a collection and optionally define a request name. If left blank, a default name "(method/endpoint)" is used.
                        </div>
                        <input
                            value={saveRequestName}
                            onChange={(e) => setSaveRequestName(e.target.value)}
                            placeholder="Request name (optional)"
                            className={styles.modalInput}
                        />
                        <select
                            value={saveCollectionName}
                            onChange={(e) => setSaveCollectionName(e.target.value)}
                            className={styles.modalInput}
                        >
                            <option value="">Select collection</option>
                            {collections.map((collection) => (
                                <option key={collection.id} value={collection.name}>
                                    {collection.name}
                                </option>
                            ))}
                        </select>
                        {isSelectCollectionMessage && (
                            <div className={styles.modalError}>{saveMessage}</div>
                        )}
                        <div className={styles.modalActions}>
                            <button
                                type="button"
                                onClick={() => toggleSaveDialog("close")}
                                className={styles.modalCancel}
                            >
                                Cancel
                            </button>
                            <button
                                type="button"
                                onClick={saveRequestToCollection}
                                className={styles.modalPrimary}
                            >
                                Save Request
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </main>
    );
}